static const int kCharTableCount = 23;

// notation for (internal char name, move-id), or nullptr. "" = known followup,
// notation not yet filled.
inline const char* Lookup(const char* charName, short moveId) {
    if (!charName) return nullptr;
    for (int t = 0; t < kCharTableCount; ++t) {
        if (std::strcmp(kCharTables[t].name, charName) != 0) continue;
        const CharTable& ct = kCharTables[t];
        for (int i = 0; i < ct.count; ++i)
            if (ct.entries[i].id == moveId) return ct.entries[i].note;
        return nullptr;
    }
    return nullptr;
}

